INSERT INTO producto (id_producto, id_tipo_producto, nombre, descripcion, precio, fecha_alta, fecha_baja) VALUES
(1, 1, 'Lámpara Táctil de Duo dormilón', 'La lámpara táctil de Duo dormilón es una lámpara de luz tenue que se activa al tacto y que podrás colocar donde sea que necesites algo de tranquilidad: tu escritorio, tus repisas, la habitación de tu bebé o el rincón donde deberías estar completando tus lecciones. Toca una vez para un brillo suave o más veces para regular la intensidad. Es cálido, blandito y está feliz de iluminar tu día. Silicona suave LED cálido con 3 niveles de intensidad Requiere 3 pilas AAA, no incluidas Medidas: 19 x 12.7 x 7.6 cm (7.5" x 5" x 3") Este artículo se envía desde EE. UU.', 53.48, CAST('2026-04-15' AS DATETIME), NULL),
(2, 1, 'Juego de tazas Duo & Lily BFF', 'Nada dice "mejores amigos para siempre" como un juego de cilindros con líquido caliente. Descubre el set de tazas Duo & Lily BFF. Quédate con uno y regala el otro a un amigo. O quédate con los dos y reflexiona sobre tu existencia. Sea como sea, seguro que te sentirás más cálido con estas tazas tan especiales. Cerámica esmaltada con detalles pintados. Apto para lavavajillas y microondas. Medidas: 4" x 9.5" (juntos), 4" x 5.75" x 4.5" (individual) Este artículo se envía desde EE. UU.', 71.34, CAST('2026-04-15' AS DATETIME), NULL),
(3, 1, 'Molde del lado dulce del duo', 'El Molde Dulce de Duo es lo único que se interpone entre tú y 8 piezas de chocolate con forma de trasero de Duo. Así que baja las cortinas, enciende una vela y crea dulces como búhos para saborear solo o compartir con amigos. Silicona verde suave Apto para lavavajillas y microondas. Medidas: 8,5" x 4,75" x 1" Este artículo se envía desde EE. UU.', 26.70, CAST('2026-04-15' AS DATETIME), NULL),
(4, 1, 'Llavero de peluche de la rosa de Oscar', '¿Te aferras a tus sentimientos? Quizás sea hora de que alguien más se aferre a ti con el llavero Rosa de Oscar. Con una romántica rosa en la boca y el dije característico de Oscar, este llavero añade el toque perfecto de dramatismo a tu bolso de diario, bolso de trabajo o bolso lleno de poesía. 4" de alto Con detalles bordados y rosa de fieltro suave. Cierre de anillo de metal Apto para mayores de 3 años Este artículo se envía desde EE. UU.', 26.70, CAST('2026-04-15' AS DATETIME), NULL),
(5, 1, 'Conjunto de pins Juntos para siempre', 'Nada dice "pertenecemos juntos" como nuestro Set de Pins Juntos para Siempre. Combínalos y Lily y Duo se entrelazarán a la perfección. Comparte un lado con alguien que te haga sentir completo. O mantenlos juntos... una invitación abierta para la persona que amas. Medidas: 2" x 2" (juntos), 2" x 1" (individual) Pin de metal y esmalte Respaldos de caucho personalizados Este artículo se envía desde EE. UU.', 26.70, CAST('2026-04-15' AS DATETIME), NULL),
(6, 1, 'Llavero de caja sorpresa de peluche Duo', 'Una caja. Un dúo. Cero pistas. Esto no es solo un llavero. Es un juego de ruleta emocional. Cada caja sorpresa de peluches dúo esconde uno de cinco mini llaveros de peluche: suaves, blanditos y listos para colgar en tu bolso, tus llaves o donde sea. ¿Conseguirás un dúo kawaii, impactado o empapado? ¿O conseguirás el raro dúo muerto, observando desde el más allá? Quizás consigas el ultrarraro dúo fénix, de vuelta de las cenizas y más atractivo que nunca. ¡Anímate, prueba tu suerte! Apto para mayores de 3 años Tela de felpa súper suave con llavero de metal. Medidas: 5,25 x 5,25 x 3 pulgadas', 30.27, CAST('2026-04-15' AS DATETIME), NULL),
(7, 1, 'Caja Sorpresa de Duo', '¡Pon tu suerte a prueba! Estas cajas sorpresa traen 7 diseños de Duo basados en los diseños más populares de nuestro widget… pero eso no es todo: ¡cada caja guarda un secreto! ¿Serás parte del 1 % que obtiene el Duo súper raro? Solo hay una forma de descubrirlo. Si ordenas un set de 12 cajas, recibirás un exhibidor especial para la colección. Recomendado de 15 años en adelante Material PVC Medidas: 6.9 x 6.9 x 6.9 cm (2.75" x 2.75" x 2.75")', 26.70, CAST('2026-04-15' AS DATETIME), NULL),
(8, 1, 'Máscara de Duo', 'No hay nada más aterrador que ver a Duo acercarse cuando no has completado tu lección del día. Con esta máscara, pordrás asustar a todos tus amigos para recordarles que completen sus lecciones de Duolingo (o sufriran las consecuencias). Ya sea que se trate de Halloween o de una broma al azar, este disfraz tan lindo como terrorífico dará mucho de que hablar. 100% poliéster Recomendado de 14 años en adelante Ojos con malla para poder ver Medida única', 76.70, CAST('2026-04-15' AS DATETIME), NULL),
(9, 1, 'Kit Apégate a tu Aprendizaje', 'Este kit trae todo lo que necesitas para que no pierdas el camino a tu meta: notas adhesivas para recordatorios rápidos, marcadores para organizarte y un señalador de metal de Duo (para que te vigile te y juzgue si no practicas). El kit fue creado para combinarlo con tu Cuaderno compañero de aprendizaje, pero también funciona con cualquier diario, agenda o papeles al azar. ¡Apégate a tu aprendizaje y alcanzarás tus metas! El kit incluye: 4 packs de notas adhesivas ilustrados 4 packs de pestañas - 26 unidades por pack 4 packs de marcadores - 26 unidades por pack Señalador de metal de Duo', 35.63, CAST('2026-04-15' AS DATETIME), NULL),
(10, 1, 'Set de Stickers de Lily', '¡El set de stickers de la reina del sarcasmo de Duolingo ya está aquí! Dale a todo un toque del humor seco de Lily con este set de stickers de poses y expresiones de Lily. Es ideal para quienes les gusten las bandas desconocidas, las películas de horror de culto y evadir los grupos de gente. Con estos stickers de vinilo, tú también podrás juzgar a distancia a todos los que se lo merezcan. Set variado de stickers de vinilo recortados 15 stickers por set Los stickers miden entre 2 cm y 8.2 cm (0.8" a 3.25")', 17.77, CAST('2026-04-15' AS DATETIME), NULL),
(11, 1, 'Set de Stickers de Falstaff', 'En este set de stickers encontrarás al oso gruñón haciendo lo que más le gusta: dormir, comer y no esforzarse. Cada sticker de vinilo captura las emociones de Falstaff a la perfección, desde "Por favor, no me hables" a "En serio, no me hables". Puedes pegarlo en tu laptop, cuaderno o donde más lo necesites para recordar relajarte. Sugerimos que coloques los stickers de forma horizontal, para que Falstaff no se canse. Set variado de stickers de vinilo recortados 15 stickers por set Los stickers miden entre 2.4 cm y 7.6 cm (0.97" a 3")', 17.77, CAST('2026-04-15' AS DATETIME), NULL),
(12, 1, 'Set de Stickers de Zari', 'Llena todo de color y alegría con el set de stickers de Zari, el personaje más optimista de Duolingo. Cada sticker muestra a Zari en sus momentos de máximo rendimiento: emocionada, organizada y preparando un plan de aprendizaje. Pégalos en tu laptop, cuadernos o donde necesites que alguien te diga "CREE EN TI COMO YO CREO EN TI". Es ideal para fanáticos del k-pop, los dulces y los discursos motivadores que nadie pidió. Set variado de stickers de vinilo recortados 15 stickers por set Los stickers miden entre 2.4 cm y 7.3 cm (0.97" a 2.9")', 17.77, CAST('2026-04-15' AS DATETIME), NULL),
(13, 1, 'Llavero de Peluche Duo', 'Este llavero de Duo evitará que olvides tus lecciones… ¡y tus llaves! Es como el peluche clásico de Duo, solo que más pequeño para caber en tu bolsillo. Está hecho con una tela sedosa que te encantará y quedará perfecto si lo combinas con tu mochila de Duo. 7.6 x 7.6 cm (3" x 3")', 21.34, CAST('2026-04-15' AS DATETIME), NULL),
(14, 1, 'Pin de Emociones de Duo', 'Te presentamos el Pin de emociones de Duo. ¿Quieres saber qué tan dramático es tu búho favorito? Descubre qué siente al ver tu progreso, desde "¡Tú puedes!" hasta "¡¿Vas a usar un traductor automático para eso?!". Ya sea como recordatorio de tus lecciones o para celebrar tu progreso, las expresiones de Duo te ayudarán a mantener el rumbo. ¡Este compañero tan versátil siempre te acompañará, para que aprendas como nunca! Pin esmaltado de 3.3 cm x 3.1 cm (1.33" x 1.25") Gira la rueda para cambiar las expresiones', 26.70, CAST('2026-04-15' AS DATETIME), NULL),
(15, 1, 'Pack de Bolsa Esencial para Lecciones', 'Organiza tu vida y luego haz tu Duolingo diario con nuestro paquete de estuches Lesson Essentials. Con una gema, un corazón y bolígrafos, Duo el búho hizo estos estuches con cremallera para ayudarte a recordar tus lecciones y ahora está aquí para ayudarte a recordar tus llaves. Gema: 3" x 4" x .75" Corazón: 5" x 4" x .75" Bolígrafos: 9.5" x 4" x 1.5" Este artículo se envía desde EE. UU.', 62.41, CAST('2026-04-15' AS DATETIME), NULL),
(16, 1, 'Pelota de Playa Duo', 'Para aprender idiomas hay que completar ejercicios… ¡y qué mejor ejercicio que jugar en la playa! Esta pelota inflable de Duo es tan adorable como absurda. Llévala a la playa, a la piscina o a tus próximas vacaciones. ¡Duo dice que está tan redondo porque está lleno de conocimiento! 60 cm (24") de diámetro (inflada) Material: PVC', 53.48, CAST('2026-04-15' AS DATETIME), NULL),
(17, 1, 'Figura de vinilo de Lily', 'Abraza tu actitud emo interior con la figura de vinilo de Lily. Colócala en tu escritorio para una dosis diaria de humor inexpresivo y desapego introvertido... o lo que sea. A Lily le encantan las bandas desconocidas, las películas de terror clásicas y evitar a la gente, igual que a ti. Es un coleccionable existencial para quienes adoptan el estilo de vida de "¿por qué estoy aquí?". No hace falta que nos lo agradezcas. Lily tampoco lo haría. Advertencia: No se incluye el entusiasmo. Hecho de PVC La figura mide 6" de alto. Este artículo se envía desde EE. UU.', 76.70, CAST('2026-04-15' AS DATETIME), NULL),
(18, 1, 'Manual de Duolingo', 'Esto no es solo un manual: es el corazón de todo lo que hacemos. Escrito originalmente solo para empleados y pasantes, este manual captura los principios, las ocurrencias y el humor que nos caracteriza. Es una ventana a nuestra cultura, a cómo nos movemos tan rápido sin perder nuestro estilo, a por qué la frase "no hagas *****" se volvió nuestra guía principal y cómo logramos desarrollar cosas que son tan divertidas como efectivas. Ahora, por primera vez, este manual está disponible para todos. Si te gusta nuestro estilo, si te da curiosidad como desarrollador o eres de nuestros fanáticos, aquí podrás encontrar la historia real de cómo convertimos las ideas en productos, el caos en cultura y las lecciones en diversión. Incluye una versión PDF descargable gratuita con cada compra. Medidas: 16.5 x 21.6 cm (6.5" x 8.5") Libro encuadernado en espiral de 64 páginas', 15.98, CAST('2026-04-15' AS DATETIME), NULL),
(19, 1, 'Kit Para Festejar Tu Racha', 'Si estás superando todas las lecciones, es hora de celebrar tu racha. ¡Escoge el kit perfecto para la ocasión y haz una fiesta temática de Duolingo en honor a tus logros o los de un amigo! Tenemos globos, adornos para pasteles, guirnaldas, coronas de rachas y una banda que dice "Streaker". También incluye un telón de Duo de tamaño real para que puedas tomarte una foto con tu búho favorito (solo asegúrate de que todos hayan completado sus lecciones del día o podría enojarse). El kit incluye: • 12 globos de látex • 6 coronas • 2 adornos para pasteles • 1 faja • 1 guirnalda • 1 telón para colgar de 2.43 m x 2.43 m (8'' x 8'')', 107.05, CAST('2026-04-15' AS DATETIME), NULL),
(20, 1, 'Pin de esmalte de duo de anime', 'Es brillante. Es dramático. Podría enviarte a otra dimensión por saltarte la clase de japonés. El pin de esmalte Anime Duo captura a nuestro búho verde favorito en todo su esplendor kawaii: ojos grandes, estrellas y brillante (literalmente). Troquelado con detalles de ensueño y purpurina auténtica en el esmalte, este pin de edición limitada brillará tanto como tus objetivos lingüísticos. Inspirado en Duolingo: The Final Test , nuestra nueva serie de anime, es la insignia de honor definitiva para fans, coleccionistas y estudiantes. Detalles de esmalte brillante Pin de metal y esmalte de 1,5" x 1" Respaldo de caucho personalizado Este artículo se envía desde EE. UU.', 26.70, CAST('2026-04-15' AS DATETIME), NULL),
(21, 1, 'Mochila de Duo', '¡Te presentamos la mochila de Duo! Tiene la forma de nuestro búho favorito, pero esta mochila es más que una cara bonita: tiene todo lo que necesitas para progresar en tus lecciones y tu vida (o eso esperamos). Trae dos bolsillos para botellas de agua, un pequeño bolsillo con cierre de cómodo acceso y correas para cargarla y llevarla contigo a donde sea. Dentro, encontrarás el esqueleto de Duo (¿no es lógico?) y un compartimiento para mantener tu laptop a salvo. Además, trae un anillo en D para colgar llaveros (¡a Duo le encanta la compañía!) 30.4 cm de ancho x 35.5 cm de alto (12" x 14") Puede contener tabletas y laptops de hasta 33 cm de alto (13") Material: poliéster y vinilo Largo de las correas: de 38 cm a 83 cm (15" x 33") Puede almacenar botellas de hasta 700 cm³ (24 oz)', 115.98, CAST('2026-04-15' AS DATETIME), NULL),
(22, 1, 'Llavero de peluche con forma de llama de Streak', 'Mantén la llama encendida con el llavero de peluche Streak Flame: un suave y adorable recordatorio de que tu racha está a un paso de desaparecer. Los detalles de llamas bordadas y un resistente clip de plástico lo convierten en el accesorio perfecto para tu mochila Duo . 3" x 2,5" Este artículo se envía desde EE. UU.', 21.34, CAST('2026-04-15' AS DATETIME), NULL),
(23, 1, 'Pantuflas Duo', 'Ponte algo más suave... ¡como Duo! Estas pantuflas Duo te mantendrán los pies y la barriga abrigados. Hechas con tela ultrasuave y una suela de goma resistente, son justo lo que necesitas para relajarte, estudiar o ir a comprar algo. Disponibles en 3 tallas, hay una talla perfecta para todos. Eso sí, no te pongas demasiado cómodo, porque Duo siempre te vigila... Apresto: XXS-XS = M3-5, W5-7, Niños grandes 3-6 SM = M6-9, W8-11 L-XL = M10-12, W12-14 De alta calidad con tela de peluche súper suave. Suela de goma estampada Este artículo se envía desde EE. UU.', 53.48, CAST('2026-04-15' AS DATETIME), NULL),
(24, 2, 'Pantalones deportivos universitarios de Duolingo', 'Estos pantalones deportivos ofrecen comodidad y espíritu de equipo. Confeccionados en suave forro polar y diseñados para acompañarte en tus movimientos, presentan el logo de DUOLINGO en chenilla a lo largo de la pierna y un pequeño parche con la cara de Duo cerca del bolsillo para darle un toque extra de energía a tu mascota. Úsalos para el modo de estudio, el modo de relajación o el modo de protagonista accidental en un brunch. Combínalo con la camiseta universitaria Duolingo a juego para completar el uniforme. ¡Te lo has ganado! Peso medio, 9,4 oz, mezcla de algodón 80/20, preencogido Cintura elástica, puños 2 bolsillos laterales, un bolsillo en la parte trasera Parches de logotipo de chenilla bordados Parche Duo bordado cerca del bolsillo Elige una talla más grande para un ajuste más holgado Este artículo se envía desde EE. UU.', 89.20, CAST('2026-04-15' AS DATETIME), NULL),
(25, 2, 'Gorra "Learning"', 'Seguro sabías que "Learning" significa "Aprendiendo" en inglés, pero… ¿sabías que esta iba a ser tu nueva gorra favorita? Viene en color crema y verde oscuro, y tiene la palabra "LEARNING" escrita en una fuente elegante para que todos sepan que te lo estás tomando en serio. En un lado encontrarás el logo de Duolingo, y en el otro está Duo durmiendo, con un libro sobre su cabeza. Es ajustable, y está lista para protegerte del sol y de la procrastinación. ¿Quién hubiera pensado que usar una gorra te haría ver tan inteligente? 100 % algodón Diseños bordados en cada lado Gorra de cinco paneles, con broche de plástico', 53.48, CAST('2026-04-15' AS DATETIME), NULL),
(26, 2, 'Gorra de Pana de Duolingo', 'Cúbrete del sol y lleva a Duo contigo con esta cómoda gorra de pana. Contiene un logo bordado en la parte frontal y un divertido Duo asomándose en la parte posterior. Esta gorra será el saludo secreto entre tú y otros usuarios de Duolingo para identificarse. Es durable, versátil y de fácil mantenimiento: un accesorio para las cuatro estaciones del año. 100 % pana de algodón Logo bordado con relieve Gorro de 6 paneles personalizado Duo de goma asomándose en la parte posterior Correa ajustable de cuero con hebilla de metal', 60.63, CAST('2026-04-15' AS DATETIME), NULL),
(27, 2, 'Gorra de Duo', 'Esta gorra con la silueta de Duo en el frente es ideal para todas las personas que quieran transmitir su amor por Duolingo de una forma sutil y elegante. Su estilo relajado te resultará cómodo cuando te prepares para aprender un nuevo idioma o viajes al país donde se habla el idioma que estás aprendiendo. También disponible en color verde oscuro. 100 % algodón Logo bordado Gorro de 6 paneles Yupoong Classics Correa ajustable de cuero con hebilla de metal', 53.48, CAST('2026-04-15' AS DATETIME), NULL),
(28, 2, 'Sudadera de Duolingo', 'Esta cómoda sudadera viene en el color clásico de Duolingo y tiene un logo deportivo en el centro para que todos sepan que eres amigo del búho. Te abrigará cuando salgas en invierno o cuando te acuestes en tu sofá. De seguro se convertirá en parte de tu rutina diaria… ¡como tus lecciones! Mezcla 60/40 algodón Talla única Paneles laterales acanalados Logo bordado', 107.05, CAST('2026-04-15' AS DATETIME), NULL),
(29, 2, 'Camiseta de Duo Esqueleto', 'Descubre al búho dentro de ti con esta camiseta del esqueleto de Duo, tan linda como espeluznante. Esta camiseta blanca viene en talles holgados para ofrecer una gran comodidad y trae impreso uno de los diseños de nuestro widget. Como detalles, el estampado agrega un relieve distinguible al tacto, mientras que las etiquetas cosidas en la parte inferior e interna de la camiseta demuestran que se trata de un producto original. Camiseta blanca de 100 % algodón Talle holgado (oversize) Estampa con relieve Etiqueta cosida de Duolingo Etiqueta impresa el interior Lavar en frío del revés, secar a baja temperatura', 58.84, CAST('2026-04-15' AS DATETIME), NULL),
(30, 2, 'Camiseta de Duo Derretido', 'Duo se derrite. ¡Hagamos una camiseta con su cara! Este diseño tan vistoso que aparece en la camiseta es lo que sucede cuando no completas tus lecciones en Duolingo. Como puedes ver, es un problema. Esta camiseta de edición limitada trae un loco diseño original, está confeccionada con 100 % algodón premium y viene en talles holgados. El diseño fue votado como el favorito de todos los seguidores de Duo en redes sociales. Ten en cuenta que el tiempo corre: ¡ordena tu camiseta antes que Duo se derrita del todo! Camiseta color gris claro 100 % algodón Talle holgado (oversize) Estampa impresa Etiqueta cosida de Duolingo Etiqueta cosida en el interior Lavar en frío, al revés, secar a baja temperatura', 57.05, CAST('2026-04-15' AS DATETIME), NULL),
(31, 2, 'Camisa del Capitán Duo', 'Zarpa con estilo con esta camisa azul claro abotonada, que representa al Capitán Duo en sus mejores momentos náuticos. Fresca, versátil y con un estilo relajado, es perfecta para días de playa, cenas al aire libre o simplemente para lucir como si hubieras pasado los últimos 5 años en un crucero. Incluye botones personalizados, prueba de que el ocio, bien hecho, es un arte. ¡Reserva ya! ¡No olvides los shorts a juego! 100% viscosa Botones de bambú personalizados Corte holgado unisex. Consulta la tabla de tallas a continuación. Este artículo se envía desde EE. UU.', 71.34, CAST('2026-04-15' AS DATETIME), NULL),
(32, 3, 'Peluche duo de cambios de humor', 'El amor está en el aire. Y el aire es gélido. Ahora es caliente. Y ahora vuelve a ser frío. Cuando no sepas cómo expresarte, deja que el peluche Mood Swing de Duo te guíe. Presume cuando te sientas así, sin importar cómo te sientas. 6" de alto Tela de felpa súper suave Con detalles faciales bordados y diseño reversible de doble cara. Apto para mayores de 3 años Este artículo se envía desde EE. UU.', 44.55, CAST('2026-04-15' AS DATETIME), NULL),
(33, 3, 'Peluche de Duo Kawaii', 'Duo llegó al mundo del animé y está más lindo que nunca. Con ojos grandes bordados y un estilo bien kawaii, este peluche de edición limitada llegó para acompañarte mientras ves tus series favoritas y para emocionarse cuando completas tus lecciones. Viene en una caja exclusiva para coleccionistas ideal para exponerlo, regalarlo o filmar tu unboxing. Este peluche está inspirado en el Duo que aparece en la serie de anime Duolingo: la prueba final, y traerá el drama directo de la pantalla a tu sofá. 17.8 cm de alto (7") Edición limitada con detalles bordados Tela suave de alta calidad y muy abrazable Recomendado de 3 años en adelante', 62.41, CAST('2026-04-15' AS DATETIME), NULL),
(34, 3, 'Peluche de Duo', 'Con este peluche adorable de Duo, ya no olvidarás tus lecciones. Es el recordatorio perfecto para tus lecciones diarias de Duolingo. ¡Obtén el tuyo ahora, o regálaselo a alguien para que aprender sea más divertido que nunca! 21.5 cm de alto (8.5") Tela suave de alta calidad y muy abrazable Recomendado de 3 años en adelante', 53.48, CAST('2026-04-15' AS DATETIME), NULL),
(35, 3, 'Peluche de Duo Musculoso', '¿Metas? Superadas. ¿Motivación? Muchísima. Este peluche de Duo musculoso es la representación del trabajo duro. Llegó para motivarte en tus lecciones y corregir tanto tu conjugación como tu postura. Puedes abrazarlo si te animas: él no apretará TAN fuerte. 30.4 cm de alto (12") Tela suave de alta calidad y llena de músculos Recomendado de 3 años en adelante', 57.05, CAST('2026-04-15' AS DATETIME), NULL),
(36, 3, 'Peluche Big Duo', 'Conoce Big Duo: ¡18 pulgadas de motivación masiva para que sigas aprendiendo!', 160.63, CAST('2026-04-15' AS DATETIME), NULL),
(37, 3, 'Peluche de Lily', 'Conoce la versión de peluche de Lily, tan antisocial y sarcástica como la original. Puedes contarle todo sobre tus bandas desconocidas favoritas… aunque es probable que no te responda. No porque no pueda, sino porque no le interesa. 25.4 cm de alto (10") Tela suave de alta calidad y muy abrazable (aunque eso de los abrazos no le gusta mucho) Recomendado de 14 años en adelante', 57.05, CAST('2026-04-15' AS DATETIME), NULL),
(38, 3, 'Peluche de Falstaff', 'Este no es un osito cualquiera: ¡es Falstaff, el oso gruñón de Duolingo! A pesar de su cara de malhumor, Falstaff es realmente encantador. Prefiere dormir siestas y escuchar discos de jazz antes que mantener conversaciones aburridas, pero es el compañero perfecto para descansar y olvidarte un rato del mundo real. Si te gusta relajarte por la tarde y esquivar tus obligaciones, este peluche está destinado a ser tu mejor amigo. 31.7 cm de alto (12.5") Tela suave de alta calidad y muy abrazable Recomendado de 14 años en adelante', 62.41, CAST('2026-04-15' AS DATETIME), NULL),
(39, 3, 'Peluche de Zari', '¡Te presentamos el peluche de Zari! Es suave, colorida y llenará tu vida de diversión. Ya sea que estés aprendiendo matemáticas, karate o solo escuchando un poco de k-pop, te darás cuenta de que el entusiasmo de Zari es MUY contagioso. Le encantan los dulces, las crías de todos los animales y las novelas de ciencia ficción, pero está ansiosa por escuchar más sobre tus pasatiempos favoritos. ¡Es la amiga ideal! 25.4 cm de alto (10") Tela suave de alta calidad y archi súper mega abrazable Recomendado de 3 años en adelante Brazos con alambres interiores, flexibles y adaptables', 57.05, CAST('2026-04-15' AS DATETIME), NULL),
